const storeAgentData={
  station:{queue:'3 杯',queueNote:'正常範圍',longest:'8:24',longestNote:'超過承諾 3:24',load:'78%',loadNote:'接近尖峰',tablet:'已連線',time:'14:07・訂單 A109',title:'黑糖薑奶已等待 8 分 24 秒',detail:'原預估 5 分鐘；前方有 2 杯熱飲，建議更新顧客等待時間並通知吧台。',level:'高',kind:'等待超時'},
  market:{queue:'2 杯',queueNote:'正常範圍',longest:'3:18',longestNote:'承諾內',load:'52%',loadNote:'運作順暢',tablet:'已連線',time:'14:08・例行檢查',title:'目前沒有需處理的門市異常',detail:'製作佇列、原料安全水位與平板連線皆在正常範圍。',level:'✓',kind:'狀態正常'},
  campus:{queue:'5 杯',queueNote:'持續增加',longest:'6:42',longestNote:'接近承諾上限',load:'86%',loadNote:'晚間尖峰',tablet:'已連線',time:'14:06・原料預警',title:'燕麥奶預估 16:30 售罄',detail:'目前 5 瓶，低於安全水位 12 瓶；已建立跨店調撥草稿，等待店長核准。',level:'中',kind:'庫存預警'},
  office:{queue:'4 杯',queueNote:'團訂消化中',longest:'4:06',longestNote:'承諾內',load:'64%',loadNote:'午餐後平穩',tablet:'已連線',time:'14:08・例行檢查',title:'目前沒有需處理的門市異常',detail:'午餐團訂已在承諾時間內完成，製作佇列、庫存與平板連線皆正常。',level:'✓',kind:'狀態正常'},
  community:{queue:'3 杯',queueNote:'正常範圍',longest:'4:38',longestNote:'承諾內',load:'58%',loadNote:'運作順暢',tablet:'已連線',time:'14:05・原料預警',title:'檸檬低於安全水位',detail:'目前 18 顆，低於安全水位 24 顆；市場店可調撥 10 顆，等待店長核准。',level:'中',kind:'庫存預警'}
};
let storeAgentPaused=false;
function selectStoreAgent(key){const data=storeAgentData[key];if(!data)return;const noIncident=key==='market'||key==='office';const needsApproval=key==='campus'||key==='community';document.querySelectorAll('[data-store-agent]').forEach(button=>button.classList.toggle('active',button.dataset.storeAgent===key));document.querySelector('#agentQueue').textContent=data.queue;document.querySelector('#agentQueueNote').textContent=data.queueNote;document.querySelector('#agentLongest').textContent=data.longest;document.querySelector('#agentLongestNote').textContent=data.longestNote;document.querySelector('#agentLoad').textContent=data.load;document.querySelector('#agentLoadNote').textContent=data.loadNote;document.querySelector('#agentTablet').textContent=data.tablet;document.querySelector('#incidentTime').textContent=data.time;document.querySelector('#incidentTitle').textContent=data.title;document.querySelector('#incidentDetail').textContent=data.detail;document.querySelector('.incident-level>span').textContent=data.level;document.querySelector('.incident-level small').textContent=data.kind;const incident=document.querySelector('#primaryIncident');incident.classList.toggle('resolved',noIncident);document.querySelector('#incidentStatus').textContent=noIncident?'無異常':needsApproval?'需核准':'待處理';document.querySelector('#applyStoreAction').disabled=noIncident;document.querySelector('#applyStoreAction').textContent=noIncident?'無需處理':needsApproval?'建立核准草稿':'套用低風險處理'}
document.querySelectorAll('[data-store-agent]').forEach(button=>button.addEventListener('click',()=>selectStoreAgent(button.dataset.storeAgent)));
document.querySelector('#pauseStoreAgent')?.addEventListener('click',()=>{storeAgentPaused=!storeAgentPaused;const live=document.querySelector('.agent-live');live.classList.toggle('paused',storeAgentPaused);document.querySelector('#storeAgentState').textContent=storeAgentPaused?'已暫停監看':'即時監看中';document.querySelector('#pauseStoreAgent').textContent=storeAgentPaused?'恢復':'暫停';window.toast?.(storeAgentPaused?'門市 Agent 已暫停':'門市 Agent 已恢復監看')});
document.querySelector('#applyStoreAction')?.addEventListener('click',()=>{const active=document.querySelector('[data-store-agent].active')?.dataset.storeAgent;if(active==='campus'||active==='community'){window.toast?.('已建立跨店調撥草稿，等待店長核准');document.querySelector('#incidentStatus').textContent='待核准';return}const incident=document.querySelector('#primaryIncident');incident.classList.add('resolved');document.querySelector('#incidentStatus').textContent='已處理';document.querySelector('#incidentTitle').textContent='已更新等待時間並通知吧台';document.querySelector('#incidentDetail').textContent='A109 顧客預估由 5 分鐘更新為 9 分鐘；吧台已收到超時提醒，未變更訂單內容。';document.querySelector('#applyStoreAction').disabled=true;document.querySelector('#applyStoreAction').textContent='已執行';window.toast?.('門市監控 Agent 已完成低風險處理')});
document.querySelector('#simulateStorePeak')?.addEventListener('click',()=>{const section=document.querySelector('#storeAgentSection');section.classList.add('peak-mode');document.querySelector('#agentQueue').textContent='9 杯';document.querySelector('#agentQueueNote').textContent='5 分鐘內 +6 杯';document.querySelector('#agentLongest').textContent='11:08';document.querySelector('#agentLongestNote').textContent='超過承諾 6:08';document.querySelector('#agentLoad').textContent='94%';document.querySelector('#agentLoadNote').textContent='已達尖峰';document.querySelector('#incidentTime').textContent='剛剛・尖峰事件';document.querySelector('#incidentTitle').textContent='大量訂單湧入，3 杯可能超時';document.querySelector('#incidentDetail').textContent='門市監控 Agent 建議將網路點單等待時間由 5 分鐘調整為 12 分鐘，並提醒吧台先完成 3 張早到期訂單。';document.querySelector('#primaryIncident').classList.remove('resolved');document.querySelector('#incidentStatus').textContent='新異常';document.querySelector('#applyStoreAction').disabled=false;document.querySelector('#applyStoreAction').textContent='套用低風險處理';document.querySelector('#simulateStorePeak').textContent='已模擬尖峰事件';window.toast?.('已建立尖峰異常，等待門市監控 Agent 處理')});
